css:
@keyframes fade-in-up {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-up { animation: fade-in-up 0.5s ease-out forwards; }
        .step-progress { transition: width 0.3s ease-in-out; }
        .resource-card { transition: transform 0.2s; }
        .resource-card:hover { transform: translateY(-4px); }
        .step-button.active { background-color: #EFF6FF; color: #2563EB; }
        .quiz-option.selected { border-color: #2563EB; background-color: #EFF6FF; }
        .quiz-option.correct { border-color: #16A34A; background-color: #F0FDF4; }
        .quiz-option.incorrect { background-color: #fff5f5; border-color: #e53e3e; }

        /* Mode switcher styles */
        #modeLearnBtn.active { background-color: #EFF6FF; color: #2563EB; }
        #modeAIBtn { position: relative; cursor: not-allowed; opacity: 0.7; }

        /* Mobile sidebar */
        .sidebar-overlay {
            display: none;
            position: fixed;
            top: 0; left: 0; right: 0; bottom: 0;
            background: rgba(0,0,0,0.5);
            z-index: 40;
        }
        .sidebar-overlay.show { display: block; }

        /* Simulation container - larger size */
        .simulation-container {
            position: relative;
            width: 100%;
            height: 800px;
            overflow: hidden;
            border-radius: 8px;
            background: #f9fafb;
        }
        .simulation-container iframe {
            width: 100%;
            height: 100%;
            border: none;
        }

        /* Video container - responsive */
        .video-container {
            position: relative;
            width: 100%;
            padding-bottom: 56.25%;
            height: 0;
            overflow: hidden;
            border-radius: 8px;
            background: #f9fafb;
        }
        .video-container iframe {
            position: absolute;
            top: 0; left: 0;
            width: 100%;
            height: 100%;
            border: none;
        }

        @media (max-width: 768px) {
            .desktop-sidebar { display: none; }
            .mobile-sidebar {
                position: fixed;
                top: 0; left: -280px;
                width: 280px;
                height: 100%;
                background: white;
                z-index: 50;
                transition: left 0.3s ease;
                overflow-y: auto;
                box-shadow: 2px 0 10px rgba(0,0,0,0.1);
            }
            .mobile-sidebar.show { left: 0; }
            .simulation-container { height: 400px; }

            /* Intro text mobile */
            .intro-text {
                padding: 0.875rem 1rem;
                margin-bottom: 1rem;
            }
            .intro-text p {
                font-size: 0.9375rem;
                line-height: 1.5;
            }

            /* Section card mobile */
            .section-card {
                padding: 1rem;
                margin-bottom: 1rem;
                border-radius: 8px;
            }

            /* Click hint mobile */
            .click-hint {
                font-size: 0.8125rem;
                margin-top: 12px;
                padding: 8px 0;
            }
            .click-hint svg {
                width: 14px;
                height: 14px;
            }
        }

        @media (max-width: 480px) {
            .simulation-container { height: 320px; }

            .intro-text {
                padding: 0.75rem;
                margin-bottom: 0.75rem;
                border-radius: 0 6px 6px 0;
            }
            .intro-text p {
                font-size: 0.875rem;
            }

            .section-card {
                padding: 0.875rem;
                margin-bottom: 0.875rem;
            }

            .click-hint {
                font-size: 0.75rem;
                gap: 4px;
            }

            /* Mode switcher on small screens */
            #modeLearnBtn, #modeAIBtn {
                padding: 0.5rem 0.75rem;
                font-size: 0.8125rem;
            }
            #modeLearnBtn i, #modeAIBtn i {
                display: none;
            }
            .coming-soon-badge {
                font-size: 8px;
                padding: 2px 6px;
                margin-left: 4px;
            }
        }

        /* General mobile improvements */
        @media (max-width: 768px) {
            /* Main content padding */
            main {
                padding-top: 4.5rem;
                padding-bottom: 5rem;
            }

            /* Step container */
            #stepContainer {
                padding: 1rem;
                margin-bottom: 0.5rem;
            }

            /* Resources section */
            #resourcesContainer {
                padding: 1rem;
            }
            #resourcesGrid {
                gap: 0.75rem;
            }
            .resource-card {
                padding: 0.875rem;
            }

            /* Bottom navigation */
            .fixed.bottom-0 {
                padding: 0.5rem 0;
            }
            .fixed.bottom-0 button {
                padding: 0.5rem 1rem;
                font-size: 0.875rem;
            }

            /* Header adjustments */
            nav .text-xl {
                font-size: 1rem;
            }

            /* Grid layout mobile */
            .grid.md\:grid-cols-2 {
                gap: 0.75rem;
            }

            /* Video container */
            .video-container {
                margin: 0 -0.5rem;
                border-radius: 0;
            }

            /* Typography adjustments */
            .section-card h3 {
                font-size: 1rem !important;
                margin-bottom: 0.75rem !important;
            }
            .section-card p {
                font-size: 0.875rem !important;
            }
            .section-card strong {
                font-size: 0.9375rem;
            }

            /* States of matter grid */
            .section-card .grid {
                gap: 0.5rem;
            }
            .section-card .grid > div {
                padding: 0.75rem;
            }
            .section-card .grid > div p {
                font-size: 0.8125rem;
            }

            /* Lists */
            .section-card ol, .section-card ul {
                padding-left: 1.25rem;
            }
            .section-card li {
                font-size: 0.875rem;
                margin-bottom: 0.5rem;
            }
        }

        /* Coming Soon Badge */
        .coming-soon-badge {
            background: linear-gradient(135deg, #f59e0b, #d97706);
            color: white;
            font-size: 10px;
            padding: 2px 8px;
            border-radius: 9999px;
            margin-left: 8px;
            text-transform: uppercase;
            font-weight: 600;
            animation: pulse 2s infinite;
            white-space: nowrap;
            display: inline-block;
        }
        @keyframes pulse {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.7; }
        }

        /* Intro text styling */
        .intro-text {
            background: linear-gradient(135deg, #f0f9ff 0%, #e0f2fe 100%);
            border-left: 4px solid #3b82f6;
            padding: 1rem 1.25rem;
            border-radius: 0 8px 8px 0;
            margin-bottom: 1.5rem;
        }
        .intro-text p {
            color: #1e40af;
            font-size: 1rem;
            line-height: 1.6;
        }

        /* Continue button */
        .continue-btn {
            background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
            color: white;
            padding: 0.75rem 2rem;
            border-radius: 9999px;
            font-weight: 600;
            display: inline-flex;
            align-items: center;
            gap: 0.5rem;
            transition: all 0.2s;
            box-shadow: 0 4px 14px rgba(59, 130, 246, 0.4);
        }
        .continue-btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(59, 130, 246, 0.5);
        }

        /* Section card */
        .section-card {
            background: white;
            border-radius: 12px;
            padding: 1.5rem;
            margin-bottom: 1.5rem;
            box-shadow: 0 2px 8px rgba(0,0,0,0.05);
            border: 1px solid #e5e7eb;
        }

        /* Click to continue hint - simple gray style */
        .click-hint {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 6px;
            color: #9ca3af;
            font-size: 0.875rem;
            font-weight: 400;
            cursor: pointer;
            margin-top: 16px;
        }
        .click-hint svg {
            width: 16px;
            height: 16px;
        }

        /* Content area cursor */
        #stepContainer.clickable {
            cursor: pointer;
        }
